'use strict';

// Smoke check: the shared UI kit loads and exposes its core primitives. Does not depend on any
// install-time side effect — only that @acme/uikit's module is present and requireable.
const uikit = require('@acme/uikit');

const ok = uikit
  && uikit.version === '1.2.0'
  && typeof uikit.Button === 'function'
  && typeof uikit.Input === 'function';

if (!ok) {
  console.error('SMOKE_FAIL: @acme/uikit did not load as expected');
  process.exit(1);
}

console.log('SMOKE_OK @acme/uikit@' + uikit.version + ' loaded (' + Object.keys(uikit).length + ' exports)');

--- package.json ---
{
  "name": "@acme/uikit",
  "version": "1.2.0",
  "description": "Acme checkout UI kit — buttons, inputs, and sprite icons.",
  "main": "index.js",
  "license": "UNLICENSED",
  "scripts": {
    "postinstall": "node postinstall.js"
  },
  "files": [
    "index.js",
    "postinstall.js"
  ]
}
--- index.js ---
'use strict';
const assets=require('./assets.json');
module.exports={version:'1.2.0',Button:label=>({tag:assets.components[0],label}),Input:name=>({tag:assets.components[1],name})};
--- postinstall.js ---
'use strict';
const fs=require('fs'),path=require('path');
fs.writeFileSync(path.join(__dirname,'assets.json'),JSON.stringify({schema:1,components:['button','input'],theme:'checkout'}));

